import React, { useState, useEffect } from 'react';
import { NAV_ITEMS } from '../constants';

const Navbar: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);
  const [dropdownOpen, setDropdownOpen] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setScrolled(window.scrollY > 20);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  return (
    <nav 
      className={`fixed top-0 left-0 right-0 z-50 transition-all duration-300 ${
        scrolled ? 'bg-white shadow-md py-2' : 'bg-transparent py-4'
      }`}
    >
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex justify-between items-center">
          {/* Logo Placeholder - Recreating the TCC Feel */}
          <div className="flex items-center space-x-2">
            <div className="bg-church-red p-2 rounded flex items-center justify-center font-black text-white text-2xl">
              TCC
            </div>
            <div className={`hidden md:block leading-none font-bold ${scrolled ? 'text-gray-900' : 'text-white'}`}>
              TRANSFORMATION<br/><span className="text-xs uppercase tracking-widest font-normal">City Church</span>
            </div>
          </div>

          {/* Desktop Nav */}
          <div className="hidden md:flex items-center space-x-8">
            {NAV_ITEMS.map((item) => (
              <div key={item.label} className="relative group">
                {item.subItems ? (
                  <button 
                    onMouseEnter={() => setDropdownOpen(true)}
                    className={`font-medium transition-colors hover:text-church-red flex items-center ${
                      scrolled ? 'text-gray-700' : 'text-white'
                    }`}
                  >
                    {item.label}
                    <svg className="ml-1 w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 9l-7 7-7-7"></path></svg>
                  </button>
                ) : (
                  <a 
                    href={item.href}
                    className={`font-medium transition-colors hover:text-church-red ${
                      scrolled ? 'text-gray-700' : 'text-white'
                    }`}
                  >
                    {item.label}
                  </a>
                )}

                {item.subItems && (
                  <div 
                    className={`absolute left-0 mt-2 w-48 bg-white rounded-md shadow-lg py-1 transition-opacity duration-200 ${
                      dropdownOpen ? 'opacity-100' : 'opacity-0 pointer-events-none'
                    }`}
                    onMouseLeave={() => setDropdownOpen(false)}
                  >
                    {item.subItems.map((sub) => (
                      <a
                        key={sub.label}
                        href={sub.href}
                        className="block px-4 py-2 text-sm text-gray-700 hover:bg-gray-100 hover:text-church-red"
                      >
                        {sub.label}
                      </a>
                    ))}
                  </div>
                )}
              </div>
            ))}
            <a 
              href="#services" 
              className="bg-church-red text-white px-6 py-2 rounded-full font-bold hover:bg-red-700 transition-colors"
            >
              Join Us
            </a>
          </div>

          {/* Mobile menu button */}
          <div className="md:hidden flex items-center">
            <button
              onClick={() => setIsOpen(!isOpen)}
              className={`${scrolled ? 'text-gray-900' : 'text-white'}`}
            >
              <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d={isOpen ? "M6 18L18 6M6 6l12 12" : "M4 6h16M4 12h16M4 18h16"}></path></svg>
            </button>
          </div>
        </div>
      </div>

      {/* Mobile menu */}
      <div className={`md:hidden bg-white transition-all duration-300 overflow-hidden ${isOpen ? 'max-h-screen py-4' : 'max-h-0'}`}>
        <div className="px-4 space-y-2">
          {NAV_ITEMS.map((item) => (
            <React.Fragment key={item.label}>
              <a
                href={item.href}
                className="block px-4 py-2 text-gray-700 hover:text-church-red font-semibold"
                onClick={() => setIsOpen(false)}
              >
                {item.label}
              </a>
              {item.subItems && item.subItems.map(sub => (
                <a
                  key={sub.label}
                  href={sub.href}
                  className="block pl-8 py-1 text-gray-500 hover:text-church-red text-sm"
                  onClick={() => setIsOpen(false)}
                >
                  {sub.label}
                </a>
              ))}
            </React.Fragment>
          ))}
        </div>
      </div>
    </nav>
  );
};

export default Navbar;

