import React, { useState, useEffect } from 'react';
import { NAV_ITEMS } from '../constants';

interface NavbarProps {
  onNavigate: (path: string) => void;
  currentView: string;
}

const Navbar: React.FC<NavbarProps> = ({ onNavigate, currentView }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);
  const [activeDropdown, setActiveDropdown] = useState<string | null>(null);

  useEffect(() => {
    const handleScroll = () => {
      setScrolled(window.scrollY > 20 || currentView !== 'home');
    };
    window.addEventListener('scroll', handleScroll);
    handleScroll();
    return () => window.removeEventListener('scroll', handleScroll);
  }, [currentView]);

  const handleLinkClick = (e: React.MouseEvent<HTMLAnchorElement>, href: string) => {
    if (href.startsWith('/')) {
      e.preventDefault();
      onNavigate(href);
      setIsOpen(false);
      setActiveDropdown(null);
    }
  };

  const isScrolled = scrolled || currentView !== 'home';

  return (
    <nav 
      className={`fixed top-0 left-0 right-0 z-50 transition-all duration-300 ${
        isScrolled ? 'bg-white shadow-md py-2' : 'bg-transparent py-4'
      }`}
    >
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex justify-between items-center">
          <button 
            onClick={() => onNavigate('/')}
            className="flex items-center space-x-3 group"
          >
            <div className="bg-[#d32f2f] w-12 h-12 rounded-lg flex items-center justify-center font-black text-white text-xl shadow-lg group-hover:scale-105 transition-transform">
              TCC
            </div>
            <div className={`leading-none text-left font-black transition-colors ${isScrolled ? 'text-gray-900' : 'text-white'}`}>
              TRANSFORMATION<br/>
              <span className="text-[10px] uppercase tracking-[0.2em] font-bold opacity-70">City Church</span>
            </div>
          </button>

          <div className="hidden md:flex items-center space-x-8">
            {NAV_ITEMS.map((item) => (
              <div 
                key={item.label} 
                className="relative group"
                onMouseEnter={() => setActiveDropdown(item.label)}
                onMouseLeave={() => setActiveDropdown(null)}
              >
                {item.subItems ? (
                  <button className={`font-bold text-sm uppercase tracking-widest transition-colors hover:text-[#d32f2f] flex items-center ${
                    isScrolled ? 'text-gray-700' : 'text-white'
                  }`}>
                    {item.label}
                    <svg className="ml-1 w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 9l-7 7-7-7"></path></svg>
                  </button>
                ) : (
                  <a 
                    href={item.href}
                    onClick={(e) => handleLinkClick(e, item.href)}
                    className={`font-bold text-sm uppercase tracking-widest transition-colors hover:text-[#d32f2f] ${
                      isScrolled ? 'text-gray-700' : 'text-white'
                    }`}
                  >
                    {item.label}
                  </a>
                )}

                {item.subItems && (
                  <div className={`absolute left-0 mt-0 w-64 bg-white rounded-xl shadow-2xl py-2 transition-all duration-200 origin-top-left ${
                    activeDropdown === item.label ? 'opacity-100 scale-100 visible' : 'opacity-0 scale-95 invisible'
                  }`}>
                    {item.subItems.map((sub) => (
                      <a
                        key={sub.label}
                        href={sub.href}
                        onClick={(e) => handleLinkClick(e, sub.href)}
                        className="block px-6 py-3 text-sm font-bold text-gray-700 hover:bg-gray-50 hover:text-[#d32f2f] uppercase tracking-wider"
                      >
                        {sub.label}
                      </a>
                    ))}
                  </div>
                )}
              </div>
            ))}
          </div>

          <div className="md:hidden flex items-center">
            <button
              onClick={() => setIsOpen(!isOpen)}
              className={`${isScrolled ? 'text-gray-900' : 'text-white'}`}
            >
              <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d={isOpen ? "M6 18L18 6M6 6l12 12" : "M4 6h16M4 12h16M4 18h16"}></path></svg>
