      <div className={`md:hidden bg-white transition-all duration-300 overflow-hidden ${isOpen ? 'max-h-screen py-4' : 'max-h-0'}`}>
        <div className="px-4 space-y-2">
          {NAV_ITEMS.map((item) => (
            <div key={item.label}>
              <a
                href={item.href}
                onClick={(e) => !item.subItems && handleLinkClick(e, item.href)}
                className="block px-4 py-3 text-gray-700 hover:text-[#d32f2f] font-black uppercase tracking-widest text-sm border-b border-gray-50"
              >
                {item.label}
              </a>
              {item.subItems && (
                <div className="bg-gray-50 py-2">
                  {item.subItems.map(sub => (
                    <a
                      key={sub.label}
                      href={sub.href}
                      onClick={(e) => handleLinkClick(e, sub.href)}
                      className="block px-8 py-2 text-xs font-bold text-gray-500 hover:text-[#d32f2f] uppercase tracking-widest"
                    >
                      {sub.label}
