import React, { useState, useEffect, useCallback } from 'react';
import Navbar from './components/Navbar';
import Hero from './components/Hero';
import About from './components/About';
import Services from './components/Services';
import Ministries from './components/Ministries';
import NextSteps from './components/NextSteps';
import ServiceInvite from './components/ServiceInvite';
import ActivitiesPage from './components/ActivitiesPage';
import KnowingGodPage from './components/KnowingGodPage';
import LovingPeoplePage from './components/LovingPeoplePage';
import TransformingWorldPage from './components/TransformingWorldPage';
import TransformationLifePage from './components/TransformationLifePage';
import Footer from './components/Footer';

type View = 'home' | 'activities' | 'knowing-god' | 'loving-people' | 'transforming-world' | 'transformation-life';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<View>('home');

  const handleLocationChange = useCallback(() => {
    const path = window.location.pathname;
    const hash = window.location.hash;

    let nextView: View = 'home';
    if (path.includes('/activities')) nextView = 'activities';
    else if (path.includes('/knowing-god')) nextView = 'knowing-god';
    else if (path.includes('/loving-people')) nextView = 'loving-people';
    else if (path.includes('/transforming-world')) nextView = 'transforming-world';
    else if (path.includes('/transformation-life')) nextView = 'transformation-life';

    if (nextView !== currentView) {
      setCurrentView(nextView);
      if (!hash) {
        window.scrollTo(0, 0);
      }
    }

    // Smooth scroll to hash if present and we are on home
    if (hash && nextView === 'home') {
      setTimeout(() => {
        const id = hash.replace('#', '');
        const element = document.getElementById(id);
        if (element) {
          element.scrollIntoView({ behavior: 'smooth' });
        }
      }, 0);
    }
  }, [currentView]);

  useEffect(() => {
    window.addEventListener('popstate', handleLocationChange);
    window.addEventListener('hashchange', handleLocationChange);
    handleLocationChange();
    return () => {
      window.removeEventListener('popstate', handleLocationChange);
      window.removeEventListener('hashchange', handleLocationChange);
    };
  }, [handleLocationChange]);

  const navigate = (path: string) => {
    window.history.pushState({}, '', path);
    handleLocationChange();
  };

  const renderContent = () => {
    switch (currentView) {
      case 'activities': return <ActivitiesPage />;
      case 'knowing-god': return <KnowingGodPage />;
      case 'loving-people': return <LovingPeoplePage />;
      case 'transforming-world': return <TransformingWorldPage />;
      case 'transformation-life': return <TransformationLifePage onNavigate={navigate} />;
      default:
        return (
          <>
            <Hero />
            <About onNavigate={navigate} />
            <Ministries />
            <Services />
            <NextSteps />
            <ServiceInvite />
          </>
        );
    }
  };

  return (
    <div className="min-h-screen">
      <Navbar onNavigate={navigate} currentView={currentView} />
      <main>
        {renderContent()}
      </main>
      <Footer onNavigate={navigate} />
    </div>
  );
};

export default App;

import React, { useState, useEffect, useCallback } from 'react';
import Navbar from './components/Navbar';
import Hero from './components/Hero';
import About from './components/About';
import Services from './components/Services';
import Ministries from './components/Ministries';
import NextSteps from './components/NextSteps';
import ServiceInvite from './components/ServiceInvite';
import ActivitiesPage from './components/ActivitiesPage';
import KnowingGodPage from './components/KnowingGodPage';
import LovingPeoplePage from './components/LovingPeoplePage';
import TransformingWorldPage from './components/TransformingWorldPage';
import TransformationLifePage from './components/TransformationLifePage';
import Footer from './components/Footer';

type View = 'home' | 'activities' | 'knowing-god' | 'loving-people' | 'transforming-world' | 'transformation-life';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<View>('home');

  const getViewFromPath = (path: string): View => {
    if (path.includes('/activities')) return 'activities';
    if (path.includes('/knowing-god')) return 'knowing-god';
    if (path.includes('/loving-people')) return 'loving-people';
    if (path.includes('/transforming-world')) return 'transforming-world';
    if (path.includes('/transformation-life')) return 'transformation-life';
    return 'home';
  };

  const handleLocationChange = useCallback(() => {
    const path = window.location.pathname;
    const hash = window.location.hash;
    const nextView = getViewFromPath(path);

    // Update view state only if different
    setCurrentView((prev) => (prev !== nextView ? nextView : prev));

    // Handle scroll logic
    if (hash && nextView === 'home') {
      setTimeout(() => {
        const id = hash.replace('#', '');
        const element = document.getElementById(id);
        if (element) {
          element.scrollIntoView({ behavior: 'smooth' });
        }
      }, 100);
    } else if (!hash) {
      window.scrollTo(0, 0);
    }
  }, []);

  useEffect(() => {
    // Initial check
    handleLocationChange();

    window.addEventListener('popstate', handleLocationChange);
    window.addEventListener('hashchange', handleLocationChange);

    return () => {
      window.removeEventListener('popstate', handleLocationChange);
      window.removeEventListener('hashchange', handleLocationChange);
    };
  }, [handleLocationChange]);

  const navigate = (path: string) => {
    if (window.location.pathname !== path) {
      window.history.pushState({}, '', path);
      handleLocationChange();
    }
  };

  const renderContent = () => {
    switch (currentView) {
      case 'activities': return <ActivitiesPage />;
      case 'knowing-god': return <KnowingGodPage />;
      case 'loving-people': return <LovingPeoplePage />;
      case 'transforming-world': return <TransformingWorldPage />;
      case 'transformation-life': return <TransformationLifePage onNavigate={navigate} />;
      default:
        return (
          <>
            <Hero />
            <About onNavigate={navigate} />
            <Ministries />
            <Services />
            <NextSteps />
            <ServiceInvite />
          </>
        );
    }
  };

  return (
    <div className="min-h-screen">
      <Navbar onNavigate={navigate} currentView={currentView} />
      <main>
        {renderContent()}
      </main>
      <Footer onNavigate={navigate} />
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { NAV_ITEMS } from '../constants';

interface NavbarProps {
  onNavigate: (path: string) => void;
  currentView: string;
}

const Navbar: React.FC<NavbarProps> = ({ onNavigate, currentView }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);
  const [activeDropdown, setActiveDropdown] = useState<string | null>(null);

  useEffect(() => {
    const handleScroll = () => {
      setScrolled(window.scrollY > 20 || currentView !== 'home');
    };
    window.addEventListener('scroll', handleScroll);
    handleScroll();
    return () => window.removeEventListener('scroll', handleScroll);
  }, [currentView]);

  const handleLinkClick = (e: React.MouseEvent<HTMLAnchorElement>, href: string) => {
    setIsOpen(false);
    setActiveDropdown(null);

    // Handle empty or placeholder links
    if (href === '#' || !href) {
      e.preventDefault();
      return;
    }

    // Handle internal page anchors
    if (href.startsWith('#')) {
      // If we are on home, let default anchor behavior work or trigger hashchange manually if needed
      // But standard browser behavior for same-page hash is usually fine.
      return;
    }

    // Handle cross-page navigation or root anchors
    if (href.startsWith('/')) {
      const [path, hash] = href.split('#');
      const currentPath = window.location.pathname;

      // If we are staying on the same logical path but changing the hash
      const isSamePath = path === currentPath || (path === '/' && (currentPath === '' || currentPath === '/'));

      if (isSamePath) {
        if (hash) {
          e.preventDefault();
          window.location.hash = hash;
          return;
        } else if (path === '/') {
          e.preventDefault();
          window.scrollTo({ top: 0, behavior: 'smooth' });
          return;
        }
      }

      // Perform a full SPA navigation
      e.preventDefault();
      onNavigate(href);
    }
  };

  const isScrolled = scrolled || currentView !== 'home';

  return (
    <nav 
      className={`fixed top-0 left-0 right-0 z-50 transition-all duration-300 ${
        isScrolled ? 'bg-white shadow-md py-2' : 'bg-transparent py-4'
      }`}
    >
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex justify-between items-center">
          <button 
            onClick={() => onNavigate('/')}
            className="flex items-center space-x-3 group"
          >
            <div className="relative w-12 h-12 bg-church-red rounded-xl flex items-center justify-center shadow-lg group-hover:scale-105 transition-transform overflow-hidden">
               <div className="absolute inset-0 bg-gradient-to-br from-white/20 to-transparent"></div>
               <span className="font-black text-white text-xl relative z-10">TCC</span>
            </div>
            <div className={`leading-none text-left font-black transition-colors ${isScrolled ? 'text-gray-900' : 'text-white'}`}>
              TRANSFORMATION<br/>
              <span className="text-[10px] uppercase tracking-[0.2em] font-bold opacity-70">City Church</span>
            </div>
          </button>

          <div className="hidden md:flex items-center space-x-8">
            {NAV_ITEMS.map((item) => (
              <div 
                key={item.label} 
                className="relative"
                onMouseEnter={() => setActiveDropdown(item.label)}
                onMouseLeave={() => setActiveDropdown(null)}
              >
                {item.subItems ? (
                  <button className={`font-bold text-sm uppercase tracking-widest transition-colors hover:text-[#d32f2f] flex items-center h-16 ${
                    isScrolled ? 'text-gray-700' : 'text-white'
                  }`}>
                    {item.label}
                    <svg className="ml-1 w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 9l-7 7-7-7"></path></svg>
                  </button>
                ) : (
                  <a 
                    href={item.href}
                    onClick={(e) => handleLinkClick(e, item.href)}
                    className={`font-bold text-sm uppercase tracking-widest transition-colors hover:text-[#d32f2f] block h-16 flex items-center ${
                      isScrolled ? 'text-gray-700' : 'text-white'
                    }`}
                  >
                    {item.label}
                  </a>
                )}

                {item.subItems && (
                  <div className={`absolute left-0 top-full -mt-2 w-64 bg-white rounded-xl shadow-2xl py-2 transition-all duration-200 origin-top-left border border-gray-100 ${
                    activeDropdown === item.label ? 'opacity-100 scale-100 visible' : 'opacity-0 scale-95 invisible'
                  }`}>
                    {item.subItems.map((sub) => (
                      <a
                        key={sub.label}
                        href={sub.href}
                        onClick={(e) => handleLinkClick(e, sub.href)}
                        className="block px-6 py-3 text-sm font-bold text-gray-700 hover:bg-gray-50 hover:text-[#d32f2f] uppercase tracking-wider"
                      >
                        {sub.label}
                      </a>
                    ))}
                  </div>
                )}
              </div>
